// ReadSessionFile reads sessionRef through ag's own session store.
//
// It is the read counterpart to WriteSessionFile, and it exists because the two
// halves were asymmetric: every agent's WriteSession routed through the store
// and so refused a SessionRef outside the agent's session directory, while the
// matching reads — ReadSession, ReadTranscript, ExtractPrompts, ExtractSummary,
// twenty call sites over eight agents — took an absolute path on trust and
// handed it to os.ReadFile. The read is the half that matters most: the path
// reaching it came from an agent hook payload, and its content is what gets
// pulled into a checkpoint.
//
// Containment is the store's, not this function's: Name rejects a ref that
// walked out of the directory, and ReadFile refuses to follow a symlink at the
// leaf. See sessionStoreForRead for the repoPath-less case.
func ReadSessionFile(ag SessionLocator, sessionRef, repoPath string) ([]byte, error) {
	if sessionRef == "" {
		return nil, errors.New("session reference (transcript path) is required")
	}

	store, err := sessionStoreForRead(ag, sessionRef, repoPath)
	if err != nil {
		return nil, err
	}
	name, err := store.Name(sessionRef)
	if err != nil {
		return nil, fmt.Errorf("read session: %w", err)
	}
	return store.ReadFile(name) //nolint:wrapcheck // preserved for os.IsNotExist at call sites
}

// sessionStoreForRead resolves the store a session read comes out of. It is
// deliberately the same rule as sessionStoreForWrite: with a repoPath, the
// agent's session directory for it, and a ref outside that directory is an
// ERROR rather than a reason to anchor somewhere else — otherwise the one input
// that fails the containment check would be the one input that disables it.
//
// Without a repoPath the ref's own directory is the only candidate there is.
// That anchor contains nothing by itself; what makes it acceptable is the same
// thing that makes it acceptable on the write side — a ref reaching this branch
// came from Entire's own resolution rather than from an agent payload — and it
// is kept because the alternative is refusing to read at all.
func sessionStoreForRead(ag SessionLocator, sessionRef, repoPath string) (*SessionStore, error) {
	if repoPath == "" {
		return OpenSessionStoreAt(ag, filepath.Dir(sessionRef))
	}

	store, err := OpenSessionStore(ag, repoPath)
	if err != nil {
		return nil, err
	}
	if _, nameErr := store.Name(sessionRef); nameErr != nil {
		return nil, fmt.Errorf("%w: %s is not inside %s's session directory %s",
			ErrOutsideSessionStore, sessionRef, ag.Name(), store.Dir())
	}
	return store, nil
}

