// TestReadSession_RefusesSessionRefOutsideTheSessionDir pins the read half of
// the session-store boundary on a real agent.
//
// SessionRef arrives in a hook payload, so it is agent-supplied input. WriteSession
// has always routed through the store and refused a ref outside the agent's own
// session directory; ReadSession handed the same value to os.ReadFile. This is
// the case that made the asymmetry exploitable — the content read here is what
// gets pulled into a checkpoint.
//
// No t.Parallel: t.Setenv.
func TestReadSession_RefusesSessionRefOutsideTheSessionDir(t *testing.T) {
	sessionDir := t.TempDir()
	t.Setenv("ENTIRE_TEST_CLAUDE_PROJECT_DIR", sessionDir)

	outside := t.TempDir()
	secret := filepath.Join(outside, "secret.jsonl")
	require.NoError(t, os.WriteFile(secret, []byte(`{"type":"user"}`+"\n"), 0o600))

	ag := NewClaudeCodeAgent()
	got, err := ag.ReadSession(&agent.HookInput{
		SessionID:  "s1",
		SessionRef: secret,
		RepoPath:   t.TempDir(),
	})

	require.ErrorIs(t, err, agent.ErrOutsideSessionStore)
	assert.Nil(t, got, "a ref outside the session directory must not be read")
}

// TestReadSession_ReadsATranscriptInsideTheSessionDir is the companion happy
// path: the boundary must not break ordinary reads.
//
// No t.Parallel: t.Setenv.
func TestReadSession_ReadsATranscriptInsideTheSessionDir(t *testing.T) {
	sessionDir := t.TempDir()
	t.Setenv("ENTIRE_TEST_CLAUDE_PROJECT_DIR", sessionDir)

	ref := filepath.Join(sessionDir, "s1.jsonl")
	require.NoError(t, os.WriteFile(ref, []byte(`{"type":"user"}`+"\n"), 0o600))

	ag := NewClaudeCodeAgent()
	got, err := ag.ReadSession(&agent.HookInput{
		SessionID:  "s1",
		SessionRef: ref,
		RepoPath:   t.TempDir(),
	})

	require.NoError(t, err)
	require.NotNil(t, got)
	assert.Equal(t, ref, got.SessionRef)
}

