package agent

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
)

// ReadSessionFile reads sessionRef through ag's own session store.
//
// It is the read counterpart to WriteSessionFile, and it exists because the two
// halves were asymmetric: every agent's WriteSession routed through the store
// and so refused a SessionRef outside the agent's session directory, while the
// matching reads — ReadSession, ReadTranscript, ExtractPrompts, ExtractSummary,
// twenty call sites over eight agents — took an absolute path on trust and
// handed it to os.ReadFile. The read is the half that matters most: the path
// reaching it came from an agent hook payload, and its content is what gets
// pulled into a checkpoint.
//
// Containment is the store's, not this function's: Name rejects a ref that
// walked out of the directory, and ReadFile refuses to follow a symlink at the
// leaf. A caller with no repo path is refused rather than contained on a
// derived base; see ReadSessionForHook for what that case does instead.
func ReadSessionFile(ag SessionLocator, sessionRef, repoPath string) ([]byte, error) {
	if sessionRef == "" {
		return nil, errors.New("session reference (transcript path) is required")
	}
	if repoPath == "" {
		return nil, errors.New("repo path is required to contain a session read")
	}

	store, err := OpenSessionStore(ag, repoPath)
	if err != nil {
		return nil, err
	}
	// Absolutize first. Name accepts a path that is ALREADY relative as a name
	// inside the store, so a relative ref would be joined onto the store
	// directory a second time and silently miss the file.
	abs, err := filepath.Abs(sessionRef)
	if err != nil {
		return nil, fmt.Errorf("resolve session reference %s: %w", sessionRef, err)
	}
	name, err := store.Name(abs)
	if err != nil {
		return nil, fmt.Errorf("%w: %s is not inside %s's session directory %s",
			ErrOutsideSessionStore, sessionRef, ag.Name(), store.Dir())
	}
	return store.ReadFile(name) //nolint:wrapcheck // preserved for os.IsNotExist at call sites
}

// ReadSessionForHook reads input.SessionRef for an agent's ReadSession.
//
// Contained when the hook carried a RepoPath, and the pre-RepoPath plain read
// when it did not. The conditional lives HERE, in one place with a name that
// says so, rather than at each of the eight ReadSession implementations — and
// deliberately NOT inside ReadSessionFile, which must either contain or refuse
// so that it cannot be used to fake a boundary.
//
// The uncontained branch is what remains of the gap: it closes as callers learn
// to set RepoPath, not by anchoring a root on the ref's own parent. See
// transcript_read_guard_test.go.
func ReadSessionForHook(ag SessionLocator, input *HookInput) ([]byte, error) {
	if input == nil {
		return nil, errors.New("hook input is nil")
	}
	if input.RepoPath == "" {
		//nolint:gosec,wrapcheck // no RepoPath: pre-containment behavior, tracked as the remaining gap
		return os.ReadFile(input.SessionRef)
	}
	return ReadSessionFile(ag, input.SessionRef, input.RepoPath)
}

