// plainReadAgent implements only ReadTranscript. The embedded nil interface is
// the package's usual guard: any other method call panics rather than silently
// returning a zero value.
type plainReadAgent struct {
	agent.Agent

	plainRef string
}

func (a *plainReadAgent) ReadTranscript(sessionRef string) ([]byte, error) {
	a.plainRef = sessionRef
	return []byte("plain"), nil
}

// repoScopedReadAgent additionally implements agent.RepoScopedTranscriptReader.
type repoScopedReadAgent struct {
	plainReadAgent

	gotRef  string
	gotRepo string
}

func (a *repoScopedReadAgent) ReadTranscriptInRepo(sessionRef, repoPath string) ([]byte, error) {
	a.gotRef, a.gotRepo = sessionRef, repoPath
	return []byte("scoped"), nil
}

// TestReadTranscriptForCheckpoint_UsesTheRepoScopedReadWhenAvailable covers the
// read that matters: this is the transcript Entire copies into the checkpoint at
// turn end, and sessionRef reached it from a hook payload.
//
// No t.Parallel: t.Chdir.
func TestReadTranscriptForCheckpoint_UsesTheRepoScopedReadWhenAvailable(t *testing.T) {
	repo := t.TempDir()
	testutil.InitRepo(t, repo)
	t.Chdir(repo)

	ag := &repoScopedReadAgent{}
	got, err := readTranscriptForCheckpoint(t.Context(), ag, "/somewhere/s1.jsonl")

	require.NoError(t, err)
	assert.Equal(t, "scoped", string(got))
	assert.Equal(t, "/somewhere/s1.jsonl", ag.gotRef)
	assert.NotEmpty(t, ag.gotRepo, "the repo-scoped read must receive a worktree root")
	assert.Empty(t, ag.plainRef, "the uncontained read must not also run")
}

// TestReadTranscriptForCheckpoint_FallsBackForAgentsWithoutTheCapability pins
// the additive half: an agent that does not implement the capability — every
// external plugin that has not declared it — keeps the behavior it had.
//
// No t.Parallel: t.Chdir.
func TestReadTranscriptForCheckpoint_FallsBackForAgentsWithoutTheCapability(t *testing.T) {
	repo := t.TempDir()
	testutil.InitRepo(t, repo)
	t.Chdir(repo)

	ag := &plainReadAgent{}
	got, err := readTranscriptForCheckpoint(t.Context(), ag, "/somewhere/s1.jsonl")

	require.NoError(t, err)
	assert.Equal(t, "plain", string(got))
	assert.Equal(t, "/somewhere/s1.jsonl", ag.plainRef)
}

// TestReadTranscriptForCheckpoint_FallsBackOutsideARepository keeps capture
// working where there is no worktree root to scope to — the no-repo session path
// is real (see binding_norepo.go), and containment is not worth failing a
// checkpoint over.
//
// No t.Parallel: t.Chdir.
func TestReadTranscriptForCheckpoint_FallsBackOutsideARepository(t *testing.T) {
	t.Chdir(t.TempDir())

	ag := &repoScopedReadAgent{}
	got, err := readTranscriptForCheckpoint(t.Context(), ag, "/somewhere/s1.jsonl")

	require.NoError(t, err)
	assert.Equal(t, "plain", string(got))
	assert.Empty(t, ag.gotRepo, "with no worktree root there is nothing to scope to")
}

