// echoArgsInfoJSON declares the repo-scoped capability.
const echoArgsInfoJSON = `{"protocol_version":1,"name":"test","type":"Test","description":"d",` +
	`"capabilities":{"repo_scoped_transcript_reader":true}}`

// undeclaredInfoJSON is the same plugin without the declaration — the shape
// every plugin built before this capability existed has.
const undeclaredInfoJSON = `{"protocol_version":1,"name":"test","type":"Test","description":"d",` +
	`"capabilities":{}}`

// echoArgsScript answers read-transcript by echoing its own argv, so a test can
// assert which flags the CLI actually passed to the plugin.
func echoArgsScript(infoJSON string) string {
	return `#!/bin/sh
case "$1" in
  info) echo '` + infoJSON + `' ;;
  read-transcript) shift; echo "ARGS:$*" ;;
  *) echo '{}' ;;
esac
`
}

// TestReadTranscriptInRepo_PassesRepoPathToThePlugin pins the wire form of the
// capability: the plugin is invoked with --repo-path alongside --session-ref.
func TestReadTranscriptInRepo_PassesRepoPathToThePlugin(t *testing.T) {
	t.Parallel()

	if _, err := exec.LookPath("sh"); err != nil {
		t.Skip("sh not available")
	}

	binPath := testBinaryDir(t, echoArgsScript(echoArgsInfoJSON))
	ea := newExternalAgent(t, binPath)

	out, err := ea.ReadTranscriptInRepo("/sessions/s1.jsonl", "/repo")
	if err != nil {
		t.Fatalf("ReadTranscriptInRepo: %v", err)
	}
	got := string(out)
	for _, want := range []string{"--session-ref", "/sessions/s1.jsonl", "--repo-path", "/repo"} {
		if !strings.Contains(got, want) {
			t.Errorf("plugin argv %q missing %q", strings.TrimSpace(got), want)
		}
	}
}

// TestReadTranscriptInRepo_UndeclaredPluginIsNeverOffered is the compatibility
// guarantee that makes this additive.
//
// A plugin built before this capability existed omits the field, it unmarshals
// to false, and the As* gate must therefore not hand it out — so that plugin's
// argument parser never sees --repo-path. Without this, adding the flag would
// break every existing plugin.
func TestReadTranscriptInRepo_UndeclaredPluginIsNeverOffered(t *testing.T) {
	t.Parallel()

	if _, err := exec.LookPath("sh"); err != nil {
		t.Skip("sh not available")
	}

	binPath := testBinaryDir(t, echoArgsScript(undeclaredInfoJSON))
	ea := newExternalAgent(t, binPath)
	wrapped, err := Wrap(ea)
	if err != nil {
		t.Fatalf("Wrap: %v", err)
	}

	if _, ok := agent.AsRepoScopedTranscriptReader(wrapped); ok {
		t.Error("a plugin that did not declare the capability must not be offered it")
	}
}

// TestReadTranscriptInRepo_DeclaringPluginIsOffered is the other half.
func TestReadTranscriptInRepo_DeclaringPluginIsOffered(t *testing.T) {
	t.Parallel()

	if _, err := exec.LookPath("sh"); err != nil {
		t.Skip("sh not available")
	}

	binPath := testBinaryDir(t, echoArgsScript(echoArgsInfoJSON))
	ea := newExternalAgent(t, binPath)
	wrapped, err := Wrap(ea)
	if err != nil {
		t.Fatalf("Wrap: %v", err)
	}

	if _, ok := agent.AsRepoScopedTranscriptReader(wrapped); !ok {
		t.Error("a declaring plugin must be offered the repo-scoped read")
	}
}

