			place: func(t *testing.T, sessionDir, _ string) string {
				t.Helper()
				outside := t.TempDir()
				target := filepath.Join(outside, "secret.jsonl")
				require.NoError(t, os.WriteFile(target, []byte("SECRET\\n"), 0o600))
				ref := filepath.Join(sessionDir, "abc123.jsonl")
